use vstd::prelude::*;

verus! {

    /// Given a non‐empty index vector and a non‐empty matrix `choices` whose
    /// each row has length equal to `indices.len()`, and each index
    /// is a valid row number, build a result vector `result` of the same
    /// length as `indices` such that
    ///   result[i] = choices[ indices[i] as usize ][ i ].
    fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> (result: Vec<f64>)
        requires
            // both inputs are non‐empty
            indices@.len() > 0,
            choices@.len() > 0,
            // every row of the matrix has the same length as indices
            forall |r: nat| r < choices@.len() ==>
                choices@[r]@.len() == indices@.len(),
            // every index selects a valid row in [0 .. choices.len())
            forall |i: nat| i < indices@.len() ==>
                (indices@.index(i) as nat) < choices@.len(),
        ensures
            // the result has the same length as indices
            result@.len() == indices@.len(),
            // and for each position i,
            // result[i] == choices[ indices[i] ][ i ]
            forall |i: nat| i < result@.len() ==>
                result@.index(i)
                ==
                choices@.index(indices@.index(i) as nat)@.index(i),
    {
        let mut result: Vec<f64> = Vec::new();
        let n = indices.len();
        let mut i: usize = 0;
        // We build result by pushing one element per iteration.
        while i < n
            invariant
                // loop variant: i ≤ n
                i <= n,
                // result has grown exactly to length i
                result@.len() == (i as nat),
                // correctness of all positions < i
                forall |j: nat| j < result@.len() ==>
                    result@.index(j)
                    ==
                    choices@.index(indices@.index(j) as nat)@.index(j),
            decreases (n as nat) - (i as nat),
        {
            // fetch the row number
            let idx: usize = indices[i] as usize;
            // by the requires, idx < choices.len()
            assert(idx < choices.len());
            // each row has length n
            let row_len = choices[idx].len();
            assert(row_len == n);
            // pull out the desired element
            let v = choices[idx][i];
            // append it
            result.push(v);
            i += 1;
        }
        result
    }

}

fn main() {
    // example usage (not verified at runtime)
    let idx = Vec::from_vec([1u8, 0u8, 2u8].to_vec());
    let mat = Vec::from_vec(vec![
        vec![10.0, 11.0, 12.0],
        vec![20.0, 21.0, 22.0],
        vec![30.0, 31.0, 32.0],
    ]);
    let res = choose(idx, mat);
    // res should be [20.0, 11.0, 32.0]
    println!("{:?}", res);
}

